// Correo que recibe los recibos. Si no te llegan a la bandeja de entrada
// (Gmail oculta los correos que te vuelven a ti mismo por reenvío),
// cambia esta dirección por tu Gmail.
const DESTINO = 'info@veneiatech.de';

const b = $input.first().json.body || {};
for (const k of ['numero', 'cliente', 'pdfBase64']) {
  if (!b[k]) throw new Error('Falta el campo ' + k);
}
const buf = Buffer.from(String(b.pdfBase64), 'base64');
if (buf.length < 500 || buf.subarray(0, 4).toString() !== '%PDF') {
  throw new Error('El archivo recibido no es un PDF válido');
}
if (buf.length > 5 * 1024 * 1024) throw new Error('PDF demasiado grande');

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const money = (n) => {
  try { return new Intl.NumberFormat('es-ES', { style: 'currency', currency: b.moneda || 'EUR' }).format(Number(n) || 0); }
  catch (e) { return (Number(n) || 0).toFixed(2) + ' ' + (b.moneda || ''); }
};
const fecha = b.fecha ? b.fecha.split('-').reverse().join('/') : '';
const filas = [
  ['Cliente', b.cliente], ['País', b.pais], ['Dirección', b.direccion],
  ['Servicio', (b.servicio || '') + (b.concepto ? ' · ' + b.concepto : '')],
  ['Total del servicio', money(b.total)], ['Ingresó hoy', money(b.abono) + ' (' + (b.pct ?? 0) + ' %)'],
  ['Pagado antes', money(b.previo)], ['Saldo pendiente', money(b.saldo)], ['Método de pago', b.metodo]
].filter((r) => r[1]);

const html = "<div style='font-family:Arial,sans-serif;color:#111B30'>" +
  "<h2 style='margin:0 0 4px'>" + esc(b.tipo || 'Recibo') + ' ' + esc(b.numero) + '</h2>' +
  "<p style='margin:0 0 14px;color:#5B6680'>" + esc(fecha) + '</p>' +
  "<table style='border-collapse:collapse'>" +
  filas.map((r) => "<tr><td style='padding:4px 16px 4px 0;color:#5B6680'>" + r[0] + "</td><td style='padding:4px 0;font-weight:bold'>" + esc(r[1]) + '</td></tr>').join('') +
  "</table><p style='font-size:11px;color:#6A7389;margin-top:18px'>PDF adjunto · Recibos Veneiatech</p></div>";

const filename = String(b.filename || ('Recibo_' + b.numero + '.pdf')).replace(/[^\w.\-À-ÿ]+/g, '_');
const binario = await this.helpers.prepareBinaryData(buf, filename, 'application/pdf');

return [{
  json: {
    destino: DESTINO,
    asunto: (b.tipo || 'Recibo') + ' ' + b.numero + ' · ' + b.cliente,
    html,
    numero: b.numero
  },
  binary: { data: binario }
}];
